#include <vector>
#include <numeric>
#include <algorithm>

class Solution {
public:
    int maxPathIntersectionSum(std::vector<std::vector<int>>& grid) {
        int m = grid.size();
        int n = grid[0].size();
        long long ans = -1e18;
        for (int r = 0; r < m; ++r) {
            if (r == 0) {
                long long s = 0;
                for (int x : grid[0]) s += x;
                ans = std::max(ans, s);
            } else if (r == m - 1) {
                long long s = 0;
                for (int x : grid[m - 1]) s += x;
                ans = std::max(ans, s);
            } else {
                long long cur = 0, bestRow = -1e18;
                for (int val : grid[r]) {
                    cur = std::max((long long)val, cur + val);
                    bestRow = std::max(bestRow, cur);
                }
                ans = std::max(ans, bestRow);
            }
        }
        return ans;
    }
};

class Solution {
    public int maxPathIntersectionSum(int[][] grid) {
        int m = grid.length;
        int n = grid[0].length;
        long ans = Long.MIN_VALUE;
        for (int r = 0; r < m; r++) {
            if (r == 0) {
                long s = 0;
                for (int x : grid[0]) s += x;
                ans = Math.max(ans, s);
            } else if (r == m - 1) {
                long s = 0;
                for (int x : grid[m - 1]) s += x;
                ans = Math.max(ans, s);
            } else {
                long cur = 0, bestRow = Long.MIN_VALUE;
                for (int val : grid[r]) {
                    cur = Math.max(val, cur + val);
                    bestRow = Math.max(bestRow, cur);
                }
                ans = Math.max(ans, bestRow);
            }
        }
        return (int)ans;
    }
}

function maxPathIntersectionSum(grid) {
    const m = grid.length;
    const n = grid[0].length;
    let ans = -Infinity;
    for (let r = 0; r < m; r++) {
        if (r === 0) {
            const s = grid[0].reduce((a, b) => a + b, 0);
            ans = Math.max(ans, s);
        } else if (r === m - 1) {
            const s = grid[m - 1].reduce((a, b) => a + b, 0);
            ans = Math.max(ans, s);
        } else {
            let cur = 0, bestRow = -Infinity;
            for (const val of grid[r]) {
                cur = Math.max(val, cur + val);
                bestRow = Math.max(bestRow, cur);
            }
            ans = Math.max(ans, bestRow);
        }
    }
    return ans;
}
